import type { FluidsModule } from './types';

// The glue module (fluids.js) is generated by scripts/build_wasm.ps1 into
// ../wasm-gen/ and is not present in source control (only its type stub,
// fluids.d.ts, is). A static-path dynamic import lets Vite bundle it in
// production builds and rewrite its internal
// `new URL('fluids.wasm', import.meta.url)` into a hashed asset URL.
export async function loadFluidsModule(): Promise<FluidsModule> {
  const factory = (await import('../wasm-gen/fluids.js')).default;
  return (await factory()) as FluidsModule;
}
